diff --git a/src/bff/price-details/fetch-product-price-details.ts b/src/bff/price-details/fetch-product-price-details.ts
new file mode 100644
index 0000000..fedd4e7
--- /dev/null
+++ b/src/bff/price-details/fetch-product-price-details.ts
@@ -0,0 +1,82 @@
+import type {AWSEndpoints} from '../fetch-endpoint-directory';
+
+type FetchProductPriceDetailsOptions = {
+  endpoints: AWSEndpoints;
+  language: string;
+  advancePayment?: string;
+  advanceMonth?: string;
+  duration: string;
+  mileage: string;
+  productCode: string;
+  salesType: string;
+  userId?: string;
+  customerId?: string;
+  salesChannel?: string;
+};
+type FetchProductPriceDetailsResponse = {
+  'response-data': any;
+};
+export async function fetchProductPriceDetails({
+  endpoints,
+  language,
+  advancePayment,
+  advanceMonth,
+  duration,
+  mileage,
+  productCode,
+  salesType,
+  userId,
+  customerId,
+  salesChannel,
+}: FetchProductPriceDetailsOptions): Promise<FetchProductPriceDetailsResponse> {
+  const {origin, pathname, authorizationHeaders} = endpoints;
+
+  const headers: Record<string, string> = {
+    ...authorizationHeaders,
+  };
+  console.log(`authorizationHeaders`, authorizationHeaders);
+  if (userId) {
+    headers[`user-id`] = userId;
+  }
+
+  if (salesChannel) {
+    headers[`x-channel`] = salesChannel;
+  }
+
+  if (customerId) {
+    headers[`customer-id`] = customerId;
+  }
+
+  const queryParams = new URLSearchParams({
+    lang: language,
+    duration,
+    mileage,
+    salesType,
+    productCode,
+    fields: `FULL`,
+  });
+
+  if (advancePayment) {
+    queryParams.append(`advancedPayment`, advancePayment);
+  }
+
+  if (advanceMonth) {
+    queryParams.append(`advanceMonth`, advanceMonth);
+  }
+
+  const url = `${origin}${pathname}/price-details?${queryParams.toString()}`;
+  const response = await fetch(url, {
+    method: `GET`,
+    headers,
+  });
+
+  const data = await response.json();
+
+  if (!response.ok) {
+    throw new Error(
+      `AWS API returned ${response.status} - ${response.statusText}`,
+    );
+  }
+
+  return data;
+}

