+  /** Formatted discounted price after discount applied */
+  readonly discountedFormattedValue?: string;
+  /** Raw discounted price value */
+  readonly discountedValue?: number;
+  /** Total discount percentage (e.g., 10 for 10%) */
+  readonly totalDiscountPercentage?: number;
+}
+
+/**
+ * Promotional badge price containing discount information
+ * Used for displaying promotional pricing on product cards
+ */
+export interface PromoBadgePrice {
+  /** Discount for B2C (private) customers - tax inclusive */
+  readonly discount?: Discount;
+  /** Discount for B2B (commercial) customers - tax exclusive */
+  readonly netDiscount?: Discount;
+}
+
+/**
+ * Extended price details including promotional pricing
+ */
+export interface PriceDetailsWithDiscount {
+  readonly private: PriceDetailTypeWithDiscount;
+  readonly commercial: PriceDetailTypeWithDiscount;
+  readonly attributes: {
+    key: string;
+    value?: any;
+  }[];
