diff --git a/src/feature-app/utils/translations.ts b/src/feature-app/utils/translations.ts
new file mode 100644
index 0000000..ffd9809
--- /dev/null
+++ b/src/feature-app/utils/translations.ts
@@ -0,0 +1,71 @@
+/**
+ * Get a nested property from an object using dot notation path.
+ * @param obj - The object to get the value from
+ * @param path - Dot notation path (e.g., 'a.b.c')
+ * @param defaultValue - Default value if path not found
+ */
+const get = <T = string>(
+  obj: Record<string, any>,
+  path: string,
+  defaultValue?: T,
+): T | undefined => {
+  const keys = path.split(`.`);
+  let result: any = obj;
+
+  for (const key of keys) {
+    if (result === null || result === undefined) {
+      return defaultValue;
+    }
+    result = result[key];
+  }
+
+  return result === undefined ? defaultValue : result;
+};
+
+const regex = /\{\{([^}]+)\}\}/g;
+
+const template = (
+  str: string,
+  cb: (key: string) => string | undefined,
+): string => {
+  return str.replace(regex, (match, path) => cb(path) ?? match);
+};
+
+/**
+ * Resolves a translation string by key, with support for:
+ * - Nested key paths using dot notation (e.g., 'discount.tag')
+ * - Template variables using {{variable}} syntax
+ * - Reference to other translations using #ref.path syntax
+ *
+ * @param translations - Record of translation keys and their values
+ * @param key - The translation key to resolve
+ * @param metadata - Dynamic values for template substitution
+ * @param fallback - Fallback value if translation not found
+ * @param allowEmptyTranslation - If true, returns empty string instead of error message when not found
+ */
+export const resolveTranslation = (
+  translations: Record<string, any>,
+  key: string,
+  metadata: Record<string, any> = {},
+  fallback: string = ``,
+  allowEmptyTranslation: boolean = false,
+): string => {
+  const translation = get<string | undefined>(translations, key);
+
+  if (!translation) {
+    return (
+      fallback ||
+      (allowEmptyTranslation ? `` : `Missing translation for '${key}'`)
+    );
+  }
+
+  const resolveKey = (path: string): string | undefined => {
+    if (path.startsWith(`#ref`)) {
+      const subKey = path.replace(`#ref.`, ``);
+      return get(translations, subKey);
+    }
+    return get(metadata, path);
+  };
+
+  return template(translation, resolveKey);
+};

