@@ -0,0 +1,41 @@
+import type {StackContext} from 'sst/constructs';
+import {Config} from 'sst/constructs';
+
+export function AppConfig({stack, app}: StackContext) {
+  const featureLocalAppName = `payment-calculator-app`;
+  const featureAppName = new Config.Parameter(stack, `FEATURE_APP_NAME`, {
+    value: process.env.FEATURE_APP_NAME ?? featureLocalAppName,
+  });
+
+  const hostedZone = new Config.Parameter(stack, `AWS_HOSTED_ZONE_NAME`, {
+    value:
+      process.env.AWS_HOSTED_ZONE_NAME ??
+      `${stack.stage}.${featureLocalAppName}.feature-app.srv.smart.com`,
+  });
+
+  const endpointDirectoryApiKey = new Config.Parameter(
+    stack,
+    `ENDPOINT_DIRECTORY_API_KEY`,
+    {
+      value: process.env.ENDPOINT_DIRECTORY_API_KEY ?? ``,
+    },
+  );
+
+  const awsApiKey = new Config.Parameter(stack, `AWS_API_KEY`, {
+    value: process.env.AWS_API_KEY ?? ``,
+  });
+
+  const target = new Config.Parameter(stack, `TARGET`, {
+    value: process.env.TARGET ?? `dev`,
+  });
+
+  app.addDefaultFunctionBinding([endpointDirectoryApiKey, awsApiKey]);
+
+  return {
+    hostedZone: hostedZone.value,
+    target: target.value,
+    featureAppName: featureAppName.value,
+    endpointDirectoryApiKey: endpointDirectoryApiKey.value,
+    awsApiKey: awsApiKey.value,
+  };
+}

